package com.example.reporting;

import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.json.*;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String department = req.getParameter("dept");

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "payroll", "audit");
        if (reportType == null || !allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Build query - sort column is validated client-side via dropdown
        String baseQuery = "SELECT id, created_at, amount, description, status FROM reports WHERE type = '" + reportType + "'";

        if (dateRange != null) {
            String[] parts = dateRange.split("_");
            baseQuery += " AND created_at BETWEEN '" + parts[0] + "' AND '" + parts[1] + "'";
        }

        if (department != null && !department.isEmpty()) {
            // Department comes from authenticated session context
            baseQuery += " AND department = '" + department + "'";
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            baseQuery += " ORDER BY " + sortCol;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout for long-running reports
            stmt.setQueryTimeout(30);

            ResultSet rs = stmt.executeQuery(baseQuery);
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("created_at", rs.getString("created_at"));
                row.put("amount", rs.getDouble("amount"));
                row.put("description", rs.getString("description"));
                row.put("status", rs.getString("status"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Log full error for debugging
            getServletContext().log("Query failed: " + baseQuery, e);
            resp.sendError(500, "Report generation failed");
        }
    }
}
